ROOT.functiondef:
CREATE   function CDN.SrtKwotaAktualizacjiWUbieglychLatach(@SrtNumer int, @DataNaDzien int ,@DataRozp int, @DataPoczatekB int, @DataDok int = null, @WartoscSys tinyint = 0) 
returns decimal(15,2) 
AS 
BEGIN 
  declare @wynik decimal(15,2);
  declare @ZO int;
  declare @ZM int;
  declare @PK int;
  declare @OT int;
  declare @OTK int;
  declare @LT int;
  declare @LTK int;
  declare @AM int;
  declare @AMK int;
  declare @AMP int;
  declare @AK int;

  set  @ZO = 2144;
  set  @ZM = 2160;
  set  @OT = 2048;
  set  @OTK = 2176;
  set  @PK = 2080;
  set  @LT = 2096;
  set  @LTK = 2224;
  set  @AM = 2064;
  set  @AMK = 2192;
  set  @AMP = 6208;
  set  @AK = 2304; 

     set @wynik =
      isnull((select sum(case when @WartoscSys = 1 then SHE_KwotaUmSys else SHE_KwotaUm end)  from cdn.srthistelem where she_srtnumer = @SrtNumer and 
                            she_gidtyp = @AK  and  (she_data <= @DataPoczatekB and (isnull(@DataDok,0) = 0 or isnull(@DataDok,0) <> 0  and she_dataZap <= @DataDok) )),0)
    return(@wynik)
END
